// TH16 v1.00a Stage 4 道中波次 th16_s4_w06
// 源：st04.ecl.txt MainSub04:1566-1630（入口 1568 $CAPTURE=1 / 1569-1621 各批 %F0/%F1）
//     GirlC01:984-1002、GirlC01_at:1004-1048、GirlD01:1116-1134
// 外壳：120 帧开场缓冲后按源排程生成子敌；真实敌无敌，按源保留体碰/受击框与移动。
// 省略：ANM 表现/掉落/音效（公共口径）；弹出生 ANIM 阶段省略，ACCEL 从出生后首次效果更新开始。

const TIME_LIMIT: int = 1824;
const OPENING_BUFFER: int = 120;

// transcribe/th16/touhou-bullets.ecl：源 etSprite(0,10,6) -> type10/color6
const TH16_SHARD: int = 512;

// 源 GirlC01_at:1014 etEx(0,0,4,230,-999999,0.013f,-999999f)
//   ACCEL：a=230 帧，r=0.013 加速度标量，s<=-999990 保留效果进入时的弹角。
//   ACCEL 到期后清两轴加速度。
xformdef SHARD_ACCEL_0013 {
    @230 set_gravity(at_effect(0.013fx * cos($self_angle)), at_effect(0.013fx * sin($self_angle)));
    set_gravity(0fx, 0fx);
}

// 源 enmCreate("GirlC01", x, -32, 1000, 1000, 1)：父为 stage(0,0)、无镜像，坐标即最终位置。
sub spawn_girls(x: fx, dir: angle) {
    _ = spawn_enemy(x, -32fx, 1000, 0, 0, 0, girl_main(dir));
}

// 源 GirlC01:986-996。表现/掉落省略；框、移动、发弹保留。
async sub girl_main(dir: angle) {
    set_invuln(65535);
    // 源 setHurtbox(32,32)->r16，setHitbox(24,24)->r12（普通圆形取第一值*0.5）
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // 源 moveVel(%F0, 1.0f)
    move_vel(0, dir, 1fx, EASE_LINEAR);
    // 源 etAngle(0, %F0+%F1, 0.17453292f)，%F1=90deg
    girl_fire(dir + 90deg);
    // 源 GirlC01_300/320：wait(1000) 无限循环（出界由引擎正常回收）
    loop { wait(1000); }
}

// 源 GirlC01_at:1006-1046。etNew(0) 后配置 2 路环、固定方向；每轮 6 发、间隔 4 帧，
// 共 $B=20 轮，轮间按难度等待 30/30/15/10。
sub girl_fire(alpha: angle) {
    // 源 at_464 压栈速度 / at_612 等待：!E/!N 0.5,30 !H 1.2,15 !LO 1.5,10
    var speed: fx = 0.5fx;
    var gap: int = 30;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_HARD { speed = 1.2fx; gap = 15; }
    if rank >= RANK_LUNATIC { speed = 1.5fx; gap = 10; }

    // 源 etAim(0,3) + etCount(0,2,1)：alpha 与 alpha+180deg 两路，层数 1（仅取首速）
    var a0: angle = alpha;
    var a1: angle = alpha + 180deg;
    var ux0: fx = cos(a0);
    var uy0: fx = sin(a0);
    var ux1: fx = cos(a1);
    var uy1: fx = sin(a1);
    // 源出生 ANIM 退位移 position -= 4*velocity（每弹沿自身方向；按配置初速计）
    var back: fx = 4fx * speed;

    for round in 0..20 {
        for shot in 0..6 {
            _ = fire(TH16_SHARD, 6,
                     $self_x - back * ux0, $self_y - back * uy0,
                     speed, a0, SHARD_ACCEL_0013, none);
            _ = fire(TH16_SHARD, 6,
                     $self_x - back * ux1, $self_y - back * uy1,
                     speed, a1, SHARD_ACCEL_0013, none);
            wait(4);
        }
        wait(gap);
    }
}

// 源 GirlD01:1116-1134（$CAPTURE=1 分支）。无发弹；保留运动与碰撞框。
// GirlD01B 仅 dropMain 不同，掉落按公共口径省略，目标行为一致。
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // 源 moveVel(pi/2, 2.5) 后 moveVelTime(70, mode1, pi/2, 0.1)；mode1 = t^2
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);
    move_vel(70, 90deg, 0.1fx, EASE_QUAD_IN);
    wait(80);
    loop { wait(1000); }
}

// 源 MainSub04 排程：各批间隔 80 帧；1582-1584 / 1603-1606 在 DIFF>=1 时增员；
// 末批后 wait(500) 于 t=1060 生成 GirlD01。
async sub pattern() {
    wait(OPENING_BUFFER);

    // t=0  %F0=135deg
    spawn_girls(160fx, 135deg);
    spawn_girls(30fx, 135deg);
    wait(80);

    // t=80  %F0=45deg
    spawn_girls(-30fx, 45deg);
    spawn_girls(-160fx, 45deg);
    wait(80);

    // t=160（源 unless($DIFF>=1) goto 772）%F0=135deg
    if global(GVAR_RANK) >= RANK_NORMAL {
        spawn_girls(290fx, 135deg);
        spawn_girls(160fx, 135deg);
        spawn_girls(30fx, 135deg);
    }
    wait(80);

    // t=240  %F0=45deg
    spawn_girls(-30fx, 45deg);
    spawn_girls(-160fx, 45deg);
    spawn_girls(-290fx, 45deg);
    wait(80);

    // t=320  %F0=135deg
    spawn_girls(420fx, 135deg);
    spawn_girls(290fx, 135deg);
    spawn_girls(160fx, 135deg);
    spawn_girls(30fx, 135deg);
    wait(80);

    // t=400（源 unless($DIFF>=1) goto 1680）%F0=45deg
    if global(GVAR_RANK) >= RANK_NORMAL {
        spawn_girls(-30fx, 45deg);
        spawn_girls(-160fx, 45deg);
        spawn_girls(-290fx, 45deg);
        spawn_girls(-420fx, 45deg);
    }
    wait(80);

    // t=480  %F0=135deg
    spawn_girls(420fx, 135deg);
    spawn_girls(290fx, 135deg);
    spawn_girls(160fx, 135deg);
    spawn_girls(30fx, 135deg);
    wait(80);

    // t=560  %F0=45deg
    spawn_girls(-30fx, 45deg);
    spawn_girls(-160fx, 45deg);
    spawn_girls(-290fx, 45deg);
    spawn_girls(-420fx, 45deg);
    wait(500);

    // t=1060 源 $CAPTURE=1 -> GirlD01
    _ = spawn_enemy(0fx, -32fx, 300, 0, 0, 0, girl_d01);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
